function cumulativeInterest(perSprint, sprints) {
  return perSprint * sprints;
}

function stillCheaperToCarry(principal, perSprint, sprints) {
  return perSprint * sprints < principal;
}

function loadedCost(days, dayRate) {
  return days * dayRate;
}

function overPrincipal(principal, perSprint, sprints) {
  return Math.max(0, perSprint * sprints - principal);
}

function breakEvenSprint(principal, perSprint) {
  return Math.ceil(principal / perSprint);
}

function sprintsToRepayBy(principal, perSprint, deadlineSprint) {
  const breakEven = Math.ceil(principal / perSprint);
  return Math.max(0, deadlineSprint - breakEven);
}

function carryingCostAt(principal, perSprint, sprint) {
  return Math.round((perSprint * sprint / principal) * 100) / 100;
}
